import { DEVICE_ONLY } from './runtime.mjs';
import { openDeviceStore } from './device-store.mjs';
import { sessionSettings } from './session.mjs';
import { pwaSettings } from './pwa.mjs';
import { normalizeData, recordTask, archiveItem, restoreItem, exportHistory, exportSourceTable } from './history.mjs';
import { CloudStore } from './cloud-store.mjs';
import { refreshTheme } from './theme.js';
import { readNotionZip, importNotionZip } from './notion.mjs';
import { enhanceInputs, refreshWheels } from './wheel-picker.mjs';
import { WINDOWS, taskWindow, windowLabel, planDay } from './planner.mjs';
import { CSV_FIELDS, parseCSV, detectMapping, exportCSV, importCSV, exportICS, importICS } from './transfer.mjs';
import { CATEGORIES, dateKey, dayAdd, weekDays, uid, blankData, demoData, minutesOf, timeOf, streak, scheduleConflict, validateData } from './core.mjs';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',task:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 9 2 2 3-4m1 3h3m-9 6 2 2 3-4m1 2h3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h1m6 0h1m-8 3h1m6 0h1"/>',chart:'<path d="M4 4v16h17M8 16v-4m5 4V8m5 8V5"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',flame:'<path d="M12 3s1 4-3 7c-2 2-3 3-3 6a6 6 0 0 0 12 0c0-3-2-6-3-7 0 3-1 3-1 3 1-5-2-9-2-9Z"/>',settings:'<path d="m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h6l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',right:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',edit:'<path d="m14 5 5 5M4 20l5-1L20 8a3.5 3.5 0 0 0-5-5L4 14v6Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',play:'<path d="m9 5 11 7-11 7Z"/>',pause:'<path d="M9 5v14M15 5v14"/>',leaf:'<path d="M20 4C4 3 2 10 5 16s12 6 15-12Zm-15 16L16 9"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M5 16v5h14v-5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.leaf}</svg>`;
const tag=k=>`<span class="tag" style="--tag-color:${CATEGORIES[k].color}">${CATEGORIES[k].label}</span>`;
const fmt=(d,o={month:'long',day:'numeric',weekday:'short'})=>new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',...o}).format(new Date(d+'T12:00:00+09:00'));
const human=m=>m>=60?`${Math.floor(m/60)}<small>時間</small>${m%60?` ${m%60}<small>分</small>`:''}`:`${m}<small>分</small>`;
const today=()=>dateKey();
let storageWorks=true,loadWarning='';
let deviceStorage=null,deviceError='';
if(DEVICE_ONLY){try{deviceStorage=await openDeviceStore();}catch{deviceError='端末内の保存領域を開けません。元のデータは削除していません。通常のブラウザで開き直してください。';storageWorks=false;}}
const read=k=>{if(DEVICE_ONLY)return deviceStorage?.read(k)??null;try{return localStorage.getItem(k);}catch{storageWorks=false;return null;}};
const write=(k,v)=>{if(DEVICE_ONLY)return deviceStorage?.write(k,v)??false;try{localStorage.setItem(k,v);return true;}catch{storageWorks=false;return false;}};
const state={page:'today',demo:DEVICE_ONLY?read('tsumikasane-mode')==='demo':read('tsumikasane-mode')!=='personal',data:null,filter:'all',search:'',category:'all',selectedDay:today(),calendarAnchor:today(),recordDay:today(),timer:null};
const dataKey=()=>`tsumikasane-data-v1-${state.demo?'demo':'personal'}`;
function load(){const raw=read(dataKey());if(raw){try{const d=JSON.parse(raw);if(validateData(d))return normalizeData(d);}catch{}loadWarning='保存データを読み込めませんでした。設定から元のデータをダウンロードできます。元のデータは上書きしていません。';}return normalizeData(state.demo?demoData(today()):blankData());}
state.data=load();
if(deviceError)loadWarning=deviceError;
document.body.dataset.storageMode=DEVICE_ONLY?'device':'cloud';
let toastTimeout;
function toast(t){clearTimeout(toastTimeout);$('#toast').textContent=t;$('#toast').classList.add('visible');toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
let cloudStatus=DEVICE_ONLY?'この端末に保存済み':'クラウドを確認中';
function save(){
  if(loadWarning){toast('元の保存データを保護しています。設定からバックアップしてください。');return false;}
  const ok=write(dataKey(),JSON.stringify(state.data));
  if(DEVICE_ONLY){if(!ok)toast('端末に保存できません。全データJSONを書き出してください。');return ok;}
  if(state.demo){$('#save-status').textContent=ok?'サンプルをこのブラウザに保存':'ブラウザ保存不可';if(!ok)toast('ブラウザに保存できません。データを書き出してください。');}
  else {cloud.schedule(state.data);if(!ok)toast('端末に保存できません。クラウド保存の完了を確認してください。');}
  return ok||!state.demo;
}
const sumLogs=dates=>state.data.logs.filter(l=>dates.includes(l.date)).reduce((n,l)=>n+l.minutes,0);
const addButton=(action,label)=>`<button class="primary-button" data-action="${action}">${icon('plus')}${label}</button>`;
const empty=(message,action,label)=>`<div class="empty-state">${icon('leaf')}<p>${message}</p>${action?`<button class="secondary-button" data-action="${action}">${icon('plus')}${label}</button>`:''}</div>`;
function nav(){const items=[['today','home','今日'],['tasks','task','タスク'],['schedule','calendar','スケジュール'],['records','chart','積み上げ記録'],['assets','chart','履歴・データ']],pending=state.data.tasks.filter(t=>!t.done).length;$('#navigation').innerHTML=items.map(([k,i,l])=>`<a class="nav-item ${state.page===k?'active':''}" href="#${k}" ${state.page===k?'aria-current="page"':''}>${icon(i)}<span>${l}</span>${k==='tasks'&&pending?`<span class="nav-count">${pending}</span>`:''}</a>`).join('');$('#areas').innerHTML=Object.entries(CATEGORIES).map(([k,c])=>`<a class="area-item" href="#tasks" data-action="area" data-category="${k}"><span class="dot" style="background:${c.color}"></span>${c.label}</a>`).join('');$('#page-label').textContent=items.find(i=>i[0]===state.page)[2];$('#demo-pill').hidden=!state.demo;$('#mode-switch').textContent=state.demo?'自分のデータで始める':'サンプルを見る';$('#settings-icon').innerHTML=icon('settings');$('#header-settings').innerHTML=icon('settings');if(DEVICE_ONLY)updateDeviceStatus(deviceStorage?.status||deviceError);}
const heading=(eyebrow,title,sub,action)=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${action}</div></div>`;
function stats(week=false){const d=today(),dates=week?weekDays(d):[d],done=[...state.data.tasks,...state.data.archive.tasks].filter(t=>t.done&&dates.includes(t.doneAt)).length;return `<div class="stats">${[['clock',`${week?'今週':'今日'}の積み上げ`,human(sumLogs(dates)),'自分のための時間'],['check',`${week?'今週':'今日'}の完了タスク`,`${done}<small>件</small>`,'一歩ずつ、着実に'],['flame','積み上げの継続日数',`${streak(state.data.logs,d)}<small>日</small>`,'続けることが、力に']].map(([i,l,v,s])=>`<div class="stat-card"><span class="stat-icon">${icon(i)}</span><div><div class="stat-label">${l}</div><div class="stat-value">${v}</div></div><span class="stat-sub">${s}</span></div>`).join('')}</div>`;}
function filtered(dashboard=false){return state.data.tasks.filter(t=>(!dashboard||t.due===today()||!t.done&&(!t.due||t.due<today()))&&(state.filter==='all'||state.filter==='pending'&&!t.done||state.filter==='done'&&t.done)&&(dashboard||state.category==='all'||t.category===state.category)&&(dashboard||t.title.toLowerCase().includes(state.search.toLowerCase()))).sort((a,b)=>Number(a.done)-Number(b.done)||Number(b.priority==='high')-Number(a.priority==='high')||(a.due||'9999').localeCompare(b.due||'9999'));}
function taskRows(tasks){return tasks.length?tasks.map(t=>`<div class="task-row"><button class="check-button ${t.done?'checked':''}" data-action="toggle-task" data-id="${esc(t.id)}" aria-label="${esc(t.title)}を${t.done?'未完了に戻す':'完了する'}" aria-pressed="${t.done}">${t.done?icon('check'):''}</button><div class="task-body"><button class="task-title ${t.done?'completed':''}" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.title)}</button><div class="task-meta">${tag(t.category)}<span>${icon('clock')}${t.estimate}分</span><span class="preferred-window">${esc(windowLabel(t))}</span>${t.due&&t.due!==today()?`<span>${fmt(t.due,{month:'numeric',day:'numeric'})}${!t.done&&t.due<today()?' · 期限超過':''}</span>`:''}${t.priority==='high'&&!t.done?'<span class="priority">↗ 優先度 高</span>':''}</div></div><div class="task-tools">${!t.done?`<button class="icon-button" data-action="schedule-task" data-id="${esc(t.id)}" aria-label="${esc(t.title)}を予定に入れる">${icon('calendar')}</button>`:''}<button class="icon-button" data-action="edit-task" data-id="${esc(t.id)}" aria-label="${esc(t.title)}を編集">${icon('edit')}</button></div></div>`).join(''):empty('ここから、小さな一歩を。','new-task','タスクを追加');}
const filters=()=>`<div class="task-filters">${[['all','すべて'],['pending','未完了'],['done','完了']].map(([k,l])=>`<button class="filter-button ${state.filter===k?'active':''}" data-action="filter" data-filter="${k}">${l}</button>`).join('')}</div>`;
function tasksPanel(){return `<section class="panel"><div class="panel-heading"><h2>今日のタスク<span>${state.data.tasks.filter(t=>t.due===today()).length}</span></h2><a class="panel-link" href="#tasks">すべて見る${icon('right')}</a></div>${filters()}<div class="task-list">${taskRows(filtered(true))}</div><button class="task-add" data-action="new-task">${icon('plus')}タスクを追加する</button></section>`;}
function weekPanel(){const days=weekDays(today()),values=days.map(d=>sumLogs([d])),maximum=Math.max(...values,60),active=values.filter(v=>v>0).length;return `<section class="panel"><div class="panel-heading"><h2>今週の積み上げ</h2><a class="panel-link" href="#records">記録を見る${icon('right')}</a></div><div class="week-summary"><div class="week-title"><strong>${human(sumLogs(days))}</strong><span>${active}日間の取り組み</span></div><div class="chart" role="img" aria-label="今週の積み上げ：${days.map((d,i)=>fmt(d,{weekday:'long'})+values[i]+'分').join('、')}">${values.map((v,i)=>`<div class="chart-col ${days[i]===today()?'today':''}"><span class="chart-value">${v?v+'分':''}</span><div class="chart-bar" style="height:${v/maximum*88}%"></div></div>`).join('')}</div><div class="chart-labels">${days.map(d=>`<span class="${d===today()?'today':''}">${fmt(d,{weekday:'short'})}</span>`).join('')}</div></div><div class="week-footer">${icon('leaf')}${active?'積み重ねた時間は、ちゃんと残っています。':'最初の記録が、ここに積み重なっていきます。'}</div></section>`;}
function dayPanel(){const events=state.data.events.filter(e=>e.date===state.selectedDay).sort((a,b)=>a.start.localeCompare(b.start));return `<section class="panel"><div class="panel-heading schedule-heading"><h2>スケジュール</h2><a class="panel-link" href="#schedule" aria-label="週のスケジュールを見る">${icon('calendar')}</a></div><div class="day-selector"><button class="icon-button" data-action="day-prev" aria-label="前日">${icon('left')}</button><span>${fmt(state.selectedDay)}${state.selectedDay===today()?' · 今日':''}</span><button class="icon-button" data-action="day-next" aria-label="翌日">${icon('right')}</button></div><div class="timeline">${events.length?events.map(e=>`<div class="timeline-row"><div class="timeline-hour">${e.start}</div><div class="event-block" style="--event-color:${CATEGORIES[e.category].color}"><strong>${esc(e.title)}</strong><small>${e.start} – ${e.end} · ${minutesOf(e.end)-minutesOf(e.start)} min</small><button class="icon-button" data-action="edit-event" data-id="${esc(e.id)}" aria-label="${esc(e.title)}の予定を編集">${icon('edit')}</button></div></div>`).join(''):empty('予定はまだありません。<br>自分のための時間をつくりましょう。')}</div><button class="schedule-add" data-action="new-event">${icon('plus')}予定を追加</button></section>`;}
function focusCard(){return `<section class="focus-card"><svg class="focus-art" viewBox="0 0 64 64" aria-hidden="true"><path d="M32 55V26m0 13C12 41 9 25 9 20c21-2 25 11 23 19Zm0-10c-2-17 6-22 22-24 1 17-7 25-22 24Z" stroke="currentColor" fill="none" stroke-width="2.5"/></svg><h2>ひとつのことに、集中する。</h2><p>25分だけ、目の前のことに。<br>その時間も、立派な積み上げ。</p><div class="focus-controls"><div class="focus-time" id="timer-display">${timerDisplay()}</div><button class="primary-button" data-action="timer-toggle">${icon(state.timer?.running?'pause':'play')}${state.timer?.running?'一時停止':state.timer?'再開する':'はじめる'}</button></div>${state.timer?'<div style="display:flex;gap:15px;margin-top:15px"><button class="text-button" data-action="timer-save">ここまでを記録</button><button class="text-button" data-action="timer-reset">リセット</button></div>':''}</section>`;}
function categoriesPanel(){const days=weekDays(today()),total=sumLogs(days);return `<section class="panel category-panel"><div class="panel-heading"><h2>分野ごとの積み上げ</h2><span class="category-total">今週 · ${fmt(days[0],{month:'numeric',day:'numeric'})} – ${fmt(days[6],{month:'numeric',day:'numeric'})}</span></div><div class="category-content">${Object.entries(CATEGORIES).map(([k,c])=>{const m=state.data.logs.filter(l=>l.category===k&&days.includes(l.date)).reduce((n,l)=>n+l.minutes,0);return `<div class="category-item"><div class="category-label"><span class="dot" style="background:${c.color}"></span>${c.label}</div><div class="category-value">${human(m)}</div><div class="progress-track"><div class="progress-fill" style="background:${c.color};width:${total?m/total*100:0}%"></div></div></div>`;}).join('')}</div></section>`;}
function todayPage(){return heading('A LITTLE BETTER, EVERY DAY','今日も、一歩ずつ。<span class="sun">☀</span>','やることを整えて、自分のための時間をつくろう。',`<div><div class="date-pill">${icon('calendar')}${fmt(today())}</div>${addButton('new-task','タスクを追加')}</div>`)+stats()+`<div class="dashboard-grid"><div class="left-stack">${tasksPanel()}${weekPanel()}</div><div class="right-stack">${dayPanel()}${focusCard()}</div></div>`+categoriesPanel();}
function taskPage(){return heading('MAKE ROOM FOR WHAT MATTERS','タスクを整える。','やることを、ひとつずつ。予定に入れて、行動につなげよう。',addButton('new-task','タスクを追加'))+`<section class="panel full-tasks"><div class="toolbar"><label class="search-field"><span class="sr-only">タスクを検索</span>${icon('search')}<input id="task-search" value="${esc(state.search)}" placeholder="タスクを検索..."></label><label><span class="sr-only">分野で絞り込み</span><select id="category-filter"><option value="all">すべての分野</option>${Object.entries(CATEGORIES).map(([k,c])=>`<option value="${k}" ${state.category===k?'selected':''}>${c.label}</option>`).join('')}</select></label></div><div style="padding-top:18px">${filters()}</div><div class="task-list" id="filtered-task-list">${taskRows(filtered())}</div><button class="task-add" data-action="new-task">${icon('plus')}タスクを追加する</button></section>`;}
function schedulePage(){const days=weekDays(state.calendarAnchor);return heading('TIME FOR YOURSELF','時間をつくる。','タスクを予定に入れて、行動する時間を確保しよう。',`<button class="secondary-button" data-action="integrations">${icon('download')}データ連携</button><button class="secondary-button" data-action="plan-day">${icon('calendar')}仮配置</button>${addButton('new-event','予定を追加')}`)+`<section class="panel"><div class="panel-heading"><div class="week-nav"><button class="icon-button" data-action="week-prev" aria-label="前の週">${icon('left')}</button><strong>${fmt(days[0],{year:'numeric',month:'long',day:'numeric'})} – ${fmt(days[6],{month:'long',day:'numeric'})}</strong><button class="icon-button" data-action="week-next" aria-label="次の週">${icon('right')}</button></div><button class="secondary-button" data-action="week-today">今週</button></div><div class="calendar-wrap"><div class="calendar-head"><div></div>${days.map(d=>`<div class="calendar-day ${d===today()?'today':''}">${fmt(d,{weekday:'short'})}<strong>${Number(d.slice(-2))}</strong></div>`).join('')}</div><div class="calendar-grid"><div class="time-labels">${Array.from({length:24},(_,i)=>`<span style="top:${i*60+10}px">${String(i).padStart(2,'0')}:00</span>`).join('')}</div>${days.map(d=>`<div data-date="${d}" class="calendar-column ${d===today()?'today':''}">${Array.from({length:24},(_,i)=>`<button class="calendar-slot" data-action="calendar-slot" data-date="${d}" data-time="${String(i).padStart(2,'0')}:00" style="top:${i*60}px" aria-label="${fmt(d)} ${i}時に予定を追加"></button>`).join('')}${state.data.events.filter(e=>e.date===d).map(e=>`<button class="calendar-event" draggable="true" data-action="edit-event" data-id="${esc(e.id)}" style="--event-color:${CATEGORIES[e.category].color};top:${minutesOf(e.start)}px;height:${minutesOf(e.end)-minutesOf(e.start)}px" aria-label="${esc(e.title)} ${e.start}から${e.end}"><small>${e.start} – ${e.end}</small><strong>${esc(e.title)}</strong></button>`).join('')}</div>`).join('')}</div></div></section><p class="section-subtitle">空き時間をクリックして追加。予定はドラッグで移動、スマホは長押しして移動できます。日本時間（JST）。</p>`;}
function heatmap(){const end=weekDays(today())[6],first=dayAdd(end,-111),colors=['#edf2e8','#d8e6cc','#b1cc9d','#86ab70','#5f8952'];return `<section class="panel heatmap-panel"><div class="panel-heading"><h2>続けてきた足あと</h2><span class="heatmap-dates">直近16週間</span></div><div class="heatmap" role="img" aria-label="直近16週間の積み上げ。継続${streak(state.data.logs,today())}日。">${Array.from({length:16},(_,w)=>`<div class="heatmap-week">${Array.from({length:7},(_,d)=>{const date=dayAdd(first,w*7+d),m=sumLogs([date]);return `<div class="heatmap-cell" style="background:${date>today()?'#f8faf5':colors[m===0?0:m<30?1:m<60?2:m<120?3:4]};${date===today()?'outline:1px solid #75976a;outline-offset:1px':''}" title="${fmt(date)}：${m}分"></div>`;}).join('')}</div>`).join('')}</div><div class="heatmap-legend">少ない ${colors.map(c=>`<i style="background:${c}"></i>`).join('')} 多い</div></section>`;}
function recordPage(){const logs=state.data.logs.filter(l=>l.date===state.recordDay).slice().reverse();return heading('SMALL STEPS, REAL GROWTH','成長を、見える形に。','取り組んだ時間も、気づいたことも。今日の自分を残そう。',`<div class="record-actions"><input class="date-select" id="record-date" type="date" value="${state.recordDay}" max="${today()}" aria-label="記録を見る日付">${addButton('new-log','記録を追加')}</div>`)+stats(true)+heatmap()+`<div class="record-layout"><section class="panel"><div class="panel-heading"><div><h2>${state.recordDay===today()?'今日':fmt(state.recordDay,{month:'long',day:'numeric'})}の積み上げ</h2><div class="section-subtitle">${logs.length}件 · 合計 ${sumLogs([state.recordDay])}分</div></div></div>${logs.length?logs.map(l=>`<div class="log-row"><div class="log-icon" style="--tag-color:${CATEGORIES[l.category].color}">${icon('leaf')}</div><div class="log-body"><div class="log-title">${esc(l.title)}</div><div class="task-meta">${tag(l.category)}</div>${l.note?`<div class="log-note">${esc(l.note)}</div>`:''}</div><div class="log-duration">${l.minutes}<small>分</small></div><button class="icon-button" data-action="edit-log" data-id="${esc(l.id)}" aria-label="${esc(l.title)}の記録を編集">${icon('edit')}</button></div>`).join(''):empty('まだ記録はありません。<br>5分の取り組みも、積み上げになります。','new-log','記録を追加')}</section><div><section class="panel"><div class="panel-heading"><h2>ひとこと、振り返り。</h2>${icon('leaf')}</div><div class="reflection"><p class="reflection-hint">よかったこと、気づき、明日の自分へ。</p><label class="sr-only" for="reflection-note">${fmt(state.recordDay)}の振り返り</label><textarea id="reflection-note" maxlength="2000" placeholder="今日できたことは？\n小さな発見も、ここに残そう。">${esc(state.data.reflections[state.recordDay]||'')}</textarea><button class="primary-button" data-action="save-reflection">${icon('check')}振り返りを保存</button></div></section><div class="note-card">結果だけでなく、取り組んだ自分も認めよう。<p>今日の記録は、未来の自分への贈りものです。</p></div></div></div>`+categoriesPanel();}
function render(){const previous=$('.calendar-wrap'),scroll=previous?{top:previous.scrollTop,left:previous.scrollLeft}:null;nav();$('#main').innerHTML=(loadWarning?`<div class="storage-warning">${esc(loadWarning)}</div>`:!storageWorks?'<div class="storage-warning">ブラウザに保存できません。設定からデータを書き出してください。</div>':'')+({today:todayPage,tasks:taskPage,schedule:schedulePage,records:recordPage,assets:assetsPage}[state.page])();enhanceInputs($('#main'));if(state.page==='schedule'){const c=$('.calendar-wrap');c.scrollTop=scroll?.top??400;c.scrollLeft=scroll?.left??0;}}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close-modal" aria-label="閉じる">${icon('close')}</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal();enhanceInputs($('#modal-content'));refreshTheme();}
const field=(label,name,value='',type='text',extra='')=>`<div class="form-field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const categoryField=k=>`<div class="form-field"><label for="field-category">分野</label><select id="field-category" name="category">${Object.entries(CATEGORIES).map(([key,c])=>`<option value="${key}" ${key===k?'selected':''}>${c.label}</option>`).join('')}</select></div>`;
const noteField=v=>`<div class="form-field"><label for="field-note">メモ（任意）</label><textarea id="field-note" name="note" maxlength="2000" placeholder="気づきや、覚えておきたいこと">${esc(v||'')}</textarea></div>`;
const buttons=(type,id)=>`<p class="form-error" id="form-error" role="alert"></p><div class="form-actions">${id?`<button type="button" class="danger-button" data-action="delete-${type}" data-id="${esc(id)}">アーカイブする</button>`:''}<div class="form-actions-right"><button type="button" class="secondary-button" data-action="close-modal">キャンセル</button><button class="primary-button" type="submit">${icon('check')}${id?'変更を保存':'追加する'}</button></div></div>`;
const collection=t=>({task:'tasks',event:'events',log:'logs'}[t]);
function taskModal(id) {
  const t=state.data.tasks.find(t=>t.id===id)||{title:'',category:state.category==='all'?'learning':state.category,estimate:30,due:today(),priority:'normal',note:''};
  const w=taskWindow(t),preset=Object.keys(WINDOWS).find(k=>WINDOWS[k].start===w.start&&WINDOWS[k].end===w.end)||'custom';
  modal(id?'タスクを編集':'新しいタスク',`<form class="modal-form" data-form="task" data-id="${esc(id||'')}">${field('タスク名','title',t.title,'text','required maxlength="200" placeholder="例：英語を30分学習する"')}${categoryField(t.category)}<div class="form-grid">${field('取り組む長さ','estimate',t.estimate,'number','required min="5" max="1440" step="1"')}${field('期限（任意）','due',t.due,'date')}</div><div class="preferred-settings"><div class="form-field"><label for="field-windowPreset">取り組みたい時間帯</label><select id="field-windowPreset"><option value="custom" ${preset==='custom'?'selected':''}>自由に指定</option>${Object.entries(WINDOWS).map(([k,v])=>`<option value="${k}" ${preset===k?'selected':''}>${v.label}（${v.start}–${v.end}）</option>`).join('')}</select></div><div class="form-grid">${field('この時刻から','preferredStart',w.start,'time','required')}${field('この時刻まで','preferredEnd',w.end,'time','required')}</div><p class="field-hint">「仮配置」で、この時間帯の空き時間に予定を入れます。</p></div><div class="form-field"><label for="field-priority">優先度</label><select name="priority" id="field-priority"><option value="normal" ${t.priority==='normal'?'selected':''}>通常</option><option value="high" ${t.priority==='high'?'selected':''}>高い</option></select></div>${noteField(t.note)}${buttons('task',id)}</form>`);
}
function eventModal(id,taskId=null,preset={}) {
  const task=state.data.tasks.find(t=>t.id===taskId),start=preset.start||taskWindow(task||{}).start;
  const e=state.data.events.find(e=>e.id===id)||{title:task?.title||'',category:task?.category||'learning',date:preset.date||state.selectedDay,start,end:timeOf(Math.min(minutesOf(start)+(task?.estimate||30),1439)),taskId:task?.id||null,note:''};
  modal(id?'予定を編集':'予定を追加',`<form class="modal-form" data-form="event" data-id="${esc(id||'')}"><div class="form-field"><label for="field-taskId">タスクと紐づける（任意）</label><select name="taskId" id="field-taskId"><option value="">予定を直接入力する</option>${state.data.tasks.filter(t=>!t.done||t.id===e.taskId).map(t=>`<option value="${esc(t.id)}" ${t.id===e.taskId?'selected':''}>${esc(t.title)}</option>`).join('')}</select></div>${field('予定の名前','title',e.title,'text','required maxlength="200" placeholder="例：読書の時間"')}${categoryField(e.category)}${field('日付','date',e.date,'date','required')}<div class="form-grid">${field('開始','start',e.start,'time','required')}${field('終了','end',e.end,'time','required')}</div>${field('取り組む長さ','duration',minutesOf(e.end)-minutesOf(e.start),'number','required min="1" max="1439"')}${noteField(e.note)}<p class="field-hint">開始・終了は同じ日です。日本時間（JST）。</p>${id&&!DEVICE_ONLY?`<a class="calendar-link" href="${esc(googleEventURL(e))}" target="_blank" rel="noopener noreferrer">Google Calendarで追加画面を開く ↗</a><p class="field-hint">1回の追加用です。その後の変更・削除は同期されません。</p>`:''}${buttons('event',id)}</form>`);
}
function logModal(id,preset={}){const l=state.data.logs.find(l=>l.id===id)||{title:preset.title||'',category:'learning',date:state.recordDay,minutes:preset.minutes||30,note:''};modal(id?'積み上げ記録を編集':'積み上げを記録',`<form class="modal-form" data-form="log" data-id="${esc(id||'')}">${field('取り組んだこと','title',l.title,'text','required maxlength="200" placeholder="例：英語のリスニング"')}${categoryField(l.category)}<div class="form-grid">${field('実際に取り組んだ時間（分）','minutes',l.minutes,'number','required min="1" max="525600" step="1"')}${field('記録する日','date',l.date,'date',`required max="${today()}"`)}</div>${noteField(l.note)}<p class="field-hint">予定やタスクの目安とは別に、実際の時間を記録します。</p>${buttons('log',id)}</form>`);}
function settings(){modal('データと設定',`<div class="settings-content"><div class="setting-box"><strong style="font-size:11px">${state.demo?'サンプルモード':'自分のデータ'}</strong><small>タスク ${state.data.tasks.length}件 · 予定 ${state.data.events.length}件 · 記録 ${state.data.logs.length}件</small></div>${pwaSettings()}<h3>表示モード</h3><select class="theme-select" id="theme-preference" aria-label="表示モード"><option value="system">端末の設定に合わせる</option><option value="light">ライト</option><option value="dark">ダーク</option></select><h3>履歴とデータ資産</h3><p>完了・取り消し・アーカイブを日時つきで残します。</p><a class="secondary-button" href="#assets" data-action="close-modal">履歴・データを開く</a><h3>アプリとのデータ交換</h3><p>Notion・表計算アプリはCSV、Google Calendar・AppleカレンダーはICSで受け渡しできます。</p><button class="secondary-button" data-action="integrations">${icon('download')}インポート・エクスポート</button><h3>保存について</h3><p>${DEVICE_ONLY?'タスク・予定・達成履歴は、このブラウザの端末内保存領域に保存します。ログインは不要です。ネット接続が戻っても外へ送信しません。別の端末とは自動同期しません。定期的に全データJSONを書き出してください。':'自分のデータはログイン中のアカウント専用のクラウドへ自動保存し、この端末にも控えを残します。保存状態は画面で確認できます。サンプルは端末内だけに保存します。Googleとの自動連携は未対応です。'}</p><h3>全データのバックアップ</h3><div class="settings-buttons"><button class="secondary-button" data-action="export">${icon('download')}JSONを書き出す</button>${loadWarning?'<button class="secondary-button" data-action="export-raw">元の保存データを保護</button>':''}</div><h3>全データを復元する</h3><p>このアプリから書き出したJSONで、現在の${state.demo?'サンプル':'自分の'}データを置き換えます。</p><input type="file" id="import-file" accept=".json,application/json" aria-label="バックアップJSONを選択"><p class="form-error" id="settings-error" role="alert"></p><h3>モードを切り替える</h3><p>サンプルデータと自分のデータは別々に保存されます。</p><button class="secondary-button" data-action="switch-mode">${state.demo?'自分のデータで始める':'サンプルを見る'}</button>${sessionSettings()}</div>`);}
function confirmDelete(type,id){const item=state.data[collection(type)].find(i=>i.id===id);if(!item)return;modal('アーカイブを確認',`<div class="settings-content"><p>「${esc(item.title)}」をアーカイブします。達成履歴と元データは残ります。${type==='task'?'紐づく予定は通常の予定として残ります。':''}</p><div class="form-actions"><button class="secondary-button" data-action="close-modal">キャンセル</button><button class="primary-button" data-action="confirm-delete" data-type="${type}" data-id="${esc(id)}" style="background:#a57966;border-color:#a57966">アーカイブする</button></div></div>`);}
function download(text,name,mime='application/json'){const url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const timerKey=()=>`tsumikasane-timer-${state.demo?'demo':'personal'}`;
function loadTimer(){try{const t=JSON.parse(read(timerKey())||'null');state.timer=t&&Number.isFinite(t.endAt)&&typeof t.running==='boolean'&&Number.isFinite(t.remaining)&&t.remaining>=0&&t.remaining<=1500000?t:null;}catch{state.timer=null;}}
const persistTimer=()=>write(timerKey(),JSON.stringify(state.timer));
const remaining=()=>state.timer?state.timer.running?Math.max(0,state.timer.endAt-Date.now()):state.timer.remaining:1500000;
function timerDisplay(){const s=Math.ceil(remaining()/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
loadTimer();
setInterval(()=>{if(!state.timer)return;if(state.timer.running&&remaining()===0){state.timer.running=false;state.timer.remaining=0;persistTimer();toast('25分、おつかれさまです。「ここまでを記録」で残しましょう。');if(state.page==='today')render();}if($('#timer-display'))$('#timer-display').textContent=timerDisplay();},500);
document.addEventListener('click',event=>{
  const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(!state.demo&&!cloud.ready&&['new-task','edit-task','new-event','edit-event','new-log','edit-log','toggle-task','confirm-delete','save-reflection','apply-import','apply-plan'].includes(a)){toast(DEVICE_ONLY?deviceError||'端末の保存領域を確認しています。':'クラウドの確認が終わるまでお待ちください。');return;}
  if(a==='close-modal')$('#modal').close();
  else if(a==='new-task')taskModal();else if(a==='edit-task')taskModal(id);
  else if(a==='new-event')eventModal();else if(a==='edit-event'){if(Date.now()<(state.ignoreClickUntil||0))return;eventModal(id);}else if(a==='schedule-task')eventModal(null,id);else if(a==='calendar-slot')eventModal(null,null,{date:b.dataset.date,start:b.dataset.time});
  else if(a==='new-log')logModal();else if(a==='edit-log')logModal(id);else if(a==='settings')settings();else if(a==='integrations')integrations();else if(a==='plan-day')plannerModal();
  else if(a==='toggle-task'){const t=state.data.tasks.find(t=>t.id===id);if(!t)return;t.done=!t.done;t.doneAt=t.done?today():null;t.completedAt=t.done?new Date().toISOString():null;t.updatedAt=new Date().toISOString();recordTask(state.data,t,t.done?'completed':'reopened');save();render();toast(t.done?'タスクを完了しました。実行した時間は積み上げ記録に残せます。':'未完了に戻しました。');}
  else if(a==='filter'){state.filter=b.dataset.filter;render();}
  else if(a==='area'){state.category=b.dataset.category;state.filter='all';state.page='tasks';render();}
  else if(a==='day-prev'||a==='day-next'){state.selectedDay=dayAdd(state.selectedDay,a==='day-prev'?-1:1);render();}
  else if(a==='week-prev'||a==='week-next'){state.calendarAnchor=dayAdd(state.calendarAnchor,a==='week-prev'?-7:7);render();}
  else if(a==='week-today'){state.calendarAnchor=today();render();}
  else if(a==='save-reflection'){state.data.reflections[state.recordDay]=$('#reflection-note').value.trim();if(save())toast('振り返りを保存しました。');}
  else if(a.startsWith('delete-'))confirmDelete(a.slice(7),id);
  else if(a==='confirm-delete'){const key=collection(b.dataset.type);archiveItem(state.data,key,id);if(key==='tasks')state.data.events.forEach(e=>{if(e.taskId===id)e.taskId=null;});save();$('#modal').close();render();toast('アーカイブしました。履歴・データから復元できます。');}
  else if(a==='switch-mode'){state.demo=!state.demo;write('tsumikasane-mode',state.demo?'demo':'personal');loadWarning=deviceError;state.data=load();loadTimer();state.filter='all';state.category='all';state.search='';$('#modal').close();render();if(!state.demo)bootCloud();toast(state.demo?'サンプルデータを表示しています。':'自分のデータに切り替えました。最初のタスクを追加しましょう。');}
  else if(a==='export')download(JSON.stringify(state.data,null,2),`tsumikasane-${state.demo?'sample':'backup'}-${today()}.json`);
  else if(a==='export-raw')download(read(dataKey())||'null',`tsumikasane-original-${today()}.json`);
  else if(a==='timer-toggle'){if(!state.timer)state.timer={running:true,endAt:Date.now()+1500000,remaining:1500000};else if(state.timer.running){state.timer.remaining=remaining();state.timer.running=false;}else{if(state.timer.remaining===0){toast('時間を記録するか、リセットしてください。');return;}state.timer.endAt=Date.now()+state.timer.remaining;state.timer.running=true;}persistTimer();render();}
  else if(a==='timer-save'){const elapsed=1500000-remaining();if(elapsed<60000){toast('1分以上取り組んだら、時間を記録できます。');return;}const m=Math.floor(elapsed/60000);logModal(null,{title:'集中して取り組んだ時間',minutes:m});$('#modal-content form').dataset.fromTimer='true';}
  else if(a==='timer-reset'){state.timer=null;persistTimer();render();}
});
document.addEventListener('submit',event=>{
  const f=event.target;if(!f.dataset.form)return;event.preventDefault();const type=f.dataset.form,id=f.dataset.id,v=Object.fromEntries(new FormData(f));if(type==='csv-mapping'){previewCSV(v);return;}const key=collection(type),old=state.data[key].find(i=>i.id===id);v.title=v.title.trim();if(!v.title){$('#form-error').textContent='名前を入力してください。';return;}let item;
  if(type==='task'&&v.preferredEnd<=v.preferredStart){$('#form-error').textContent='希望終了を希望開始より後にしてください。';return;}
  if(type==='task')item={...old,id:id||uid(),title:v.title,category:v.category,estimate:Number(v.estimate),due:v.due,priority:v.priority,note:v.note.trim(),preferredStart:v.preferredStart,preferredEnd:v.preferredEnd,done:old?.done||false,doneAt:old?.doneAt||null,createdAt:old?(old.createdAt||null):new Date().toISOString(),updatedAt:new Date().toISOString()};
  if(type==='event'){if(v.end<=v.start||Number(v.duration)!==minutesOf(v.end)-minutesOf(v.start)){$('#form-error').textContent='終了時刻を開始時刻より後にしてください。';return;}item={...old,id:id||uid(),title:v.title,category:v.category,date:v.date,start:v.start,end:v.end,taskId:v.taskId||null,note:v.note.trim()};if(scheduleConflict(state.data.events,item,id)){$('#form-error').textContent='この時間には別の予定があります。重ならない時間に変更してください。';return;}}
  if(type==='log'){if(v.date>today()){$('#form-error').textContent='未来の日付に実行記録は追加できません。';return;}item={...old,id:id||uid(),title:v.title,category:v.category,date:v.date,minutes:Number(v.minutes),note:v.note.trim()};}
  const next={...state.data,[key]:state.data[key].filter(i=>i.id!==id).concat(item)};if(!validateData(next)){$('#form-error').textContent='日付・時間・文字数を確認してください。';return;}
  const index=state.data[key].findIndex(i=>i.id===id);if(index>=0)state.data[key][index]=item;else state.data[key].push(item);
  if(type==='task')recordTask(state.data,item,id?'updated':'created');
  if(type==='task')state.data.events.forEach(e=>{if(e.taskId===id){e.title=item.title;e.category=item.category;}});
  if(type==='event')state.selectedDay=item.date;if(type==='log')state.recordDay=item.date;if(f.dataset.fromTimer){state.timer=null;persistTimer();}
  save();$('#modal').close();render();toast(`${type==='task'?'タスク':type==='event'?'予定':'積み上げ記録'}を${id?'更新':'追加'}しました。`);
});
document.addEventListener('input',event=>{if(event.target.id==='task-search'){state.search=event.target.value;$('#filtered-task-list').innerHTML=taskRows(filtered());}});
document.addEventListener('change',async event=>{
  const e=event.target;if(e.id==='category-filter'){state.category=e.value;render();}
  else if(e.id==='record-date'){if(!e.value||e.value>today()){e.value=state.recordDay;return;}state.recordDay=e.value;render();}
  else if(e.id==='field-taskId'){const t=state.data.tasks.find(t=>t.id===e.value);if(t){$('#field-title').value=t.title;$('#field-category').value=t.category;$('#field-end').value=timeOf(Math.min(minutesOf($('#field-start').value)+t.estimate,1439));}}
  else if(e.id==='import-file'){const file=e.files[0];if(!file)return;const error=$('#settings-error');if(file.size>10*1024*1024){error.textContent='ファイルは10MB以内にしてください。';return;}try{const d=JSON.parse(await file.text());if(!validateData(d))throw Error('format');modal('バックアップを取り込む',`<div class="settings-content"><p>タスク${d.tasks.length}件、予定${d.events.length}件、記録${d.logs.length}件を取り込みます。現在のデータをバックアップしてから置き換えます。</p><div class="form-actions"><button class="secondary-button" data-action="close-modal">キャンセル</button><button class="primary-button" id="confirm-import">取り込む</button></div></div>`);$('#confirm-import').addEventListener('click',()=>{download(loadWarning?read(dataKey())||'null':JSON.stringify(state.data,null,2),`tsumikasane-before-import-${today()}.json`);state.data=normalizeData(d);loadWarning='';save();$('#modal').close();render();toast('バックアップを取り込みました。');},{once:true});}catch{if(error.isConnected)error.textContent='このアプリから書き出した有効なJSONを選択してください。';}}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
function googleEventURL(event) {
  const url=new URL('https://calendar.google.com/calendar/render');
  const stamp=time=>new Date(event.date+'T'+time+':00+09:00').toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
  url.search=new URLSearchParams({action:'TEMPLATE',text:event.title,dates:stamp(event.start)+'/'+stamp(event.end),details:event.note||'',ctz:'Asia/Tokyo'});
  return url.href;
}
function plannerModal() {
  const days=weekDays(state.calendarAnchor),date=state.page==='schedule'?(days.includes(state.selectedDay)?state.selectedDay:days.includes(today())?today():days[0]):state.selectedDay;
  modal('時間帯から、ざっくり仮配置',`<div class="settings-content">${field('配置する日','planner-date',date,'date','required')}<p>未完了で、期限がこの日以前・または期限未設定のタスクを配置します。すでに予定のあるタスクと、埋まっている時間は避けます。</p><div id="plan-preview"></div></div>`);
  updatePlanPreview(date);
}
function updatePlanPreview(date) {
  const result=planDay(state.data.tasks,state.data.events,date);state.planDraft={date,result};
  $('#plan-preview').innerHTML=`<div class="import-counts"><strong>${result.proposed.length}件を仮配置</strong><span>${result.skipped.length}件は配置できません</span></div>${result.proposed.map(e=>`<div class="plan-row"><span class="dot" style="background:${CATEGORIES[e.category].color}"></span><div><strong>${esc(e.title)}</strong><small>${e.start}–${e.end}</small></div></div>`).join('')}${result.skipped.length?`<details class="import-details"><summary>配置できないタスクを見る</summary>${result.skipped.map(({task,reason})=>`<p>${esc(task.title)}：${esc(reason)}</p>`).join('')}</details>`:''}${!result.proposed.length&&!result.skipped.length?'<p>対象のタスクがありません。タスクの期限・時間帯を設定してください。</p>':''}<div class="form-actions"><button class="secondary-button" data-action="close-modal">キャンセル</button><button class="primary-button" data-action="apply-plan" ${!result.proposed.length?'disabled':''}>${icon('check')}仮配置を保存</button></div>`;
}
function integrations() {
  modal('インポート・エクスポート',`<div class="settings-content"><p class="mode-notice">対象：${state.demo?'サンプルデータ':'自分のデータ'}</p><section class="integration-card"><h3>Notion・表計算アプリ</h3><p>NotionのZIPをそのまま取り込めます。CSVでタスク・積み上げ記録をやり取りすることもできます。取り込み時に列を選べます。Notion側では「CSVとマージ」またはCSVインポートを使ってください。</p><div class="settings-buttons"><button class="secondary-button" data-action="import-notion">Notion ZIPを取り込む</button><button class="secondary-button" data-action="export-csv" data-type="tasks">タスクCSV</button><button class="secondary-button" data-action="export-csv" data-type="logs">記録CSV</button><button class="secondary-button" data-action="import-csv">CSVを取り込む</button></div></section><section class="integration-card"><h3>Google Calendar・Appleカレンダー</h3><p>予定をICSで書き出し、各カレンダーのインポート機能で読み込みます。カレンダーから書き出したICSも取り込めます。同じUIDの予定は、変更を確認して更新できます。</p><div class="settings-buttons"><button class="secondary-button" data-action="export-ics">予定ICSを書き出す</button><button class="secondary-button" data-action="import-ics">ICSを取り込む</button></div><div class="integration-limit">ファイルでの受け渡しです。変更・削除の自動同期はありません。ICS取り込みは同じ日で完結する通常予定に対応しています。終日・日をまたぐ予定・繰り返し予定は、未対応として件数を表示します。</div></section><p class="field-hint">達成履歴・アーカイブ・元データの書き出しは「履歴・データ」から。JSONバックアップは「データと設定」から。CSV・ICSの取り込みでは、現在のデータに追加・更新します。</p></div>`);
}
let transferDraft;
function importFileModal(kind) {
  modal(kind==='csv'?'CSVを取り込む':'ICSを取り込む',`<div class="settings-content">${kind==='csv'?'<div class="form-field"><label for="csv-type">取り込む内容</label><select id="csv-type"><option value="tasks">タスク</option><option value="logs">積み上げ記録</option></select></div>':''}<p>ファイルを選ぶと、${kind==='csv'?'列を対応させて':'予定を読み取り、'}内容を確認できます。5MB・10,000件以内。</p><input type="file" id="transfer-file" data-kind="${kind}" accept="${kind==='csv'?'.csv,text/csv':'.ics,text/calendar'}" aria-label="${kind.toUpperCase()}ファイルを選択"><p class="form-error" id="transfer-error" role="alert"></p></div>`);
}
function csvMappingModal(parsed,type) {
  transferDraft={parsed,type};const mapping=detectMapping(parsed.headers,type);
  modal('CSVの列を対応させる',`<form class="modal-form" data-form="csv-mapping"><p class="field-hint">${parsed.rows.length}件の${type==='tasks'?'タスク':'記録'}。名前の列は必須です。分野が「学習・仕事・健康・暮らし」以外の場合は「暮らし」に置き、元の分野をメモに残します。</p><div class="csv-mapping-grid">${Object.entries(CSV_FIELDS[type]).map(([k,label])=>`<div class="form-field"><label for="mapping-${k}">${label}${k==='title'?' *':''}</label><select name="map-${k}" id="mapping-${k}" ${k==='title'?'required':''}><option value="">取り込まない</option>${parsed.headers.map(h=>`<option value="${esc(h)}" ${mapping[k]===h?'selected':''}>${esc(h)}</option>`).join('')}</select></div>`).join('')}</div><p class="form-error" id="form-error" role="alert"></p><div class="form-actions"><button type="button" class="secondary-button" data-action="integrations">戻る</button><button type="submit" class="primary-button">内容を確認</button></div></form>`);
}
function previewCSV(values) {
  try{const {parsed,type}=transferDraft;const mapping=Object.fromEntries(Object.entries(values).map(([k,v])=>[k.slice(4),v]));reviewImport(type,importCSV(parsed,mapping,type,state.data[type]));}catch(error){$('#form-error').textContent=error.message;}
}
function reviewImport(type,result) {
  transferDraft={type,result};const updates=result.updates||[],count=result.items.length+updates.length;
  modal('取り込み内容を確認',`<div class="settings-content"><p class="mode-notice">対象：${state.demo?'サンプルデータ':'自分のデータ'}</p><div class="import-counts"><strong>追加 ${result.items.length}件</strong><strong>更新 ${updates.length}件</strong><span>重複・変更なし ${result.skipped.length}件</span><span>未対応・エラー ${result.errors.length}件</span></div><div class="import-preview">${[...result.items,...updates].slice(0,8).map(item=>`<div class="plan-row"><div><strong>${esc(item.title)}</strong><small>${esc(item.date||item.due||'期限なし')}${item.start?' · '+item.start+'–'+item.end:item.minutes?' · '+item.minutes+'分':''}</small></div></div>`).join('')}${count>8?`<p>ほか ${count-8}件</p>`:''}</div>${result.errors.length?`<details class="import-details" open><summary>取り込めない内容 ${result.errors.length}件</summary>${result.errors.slice(0,8).map(e=>`<p>${e.line?'行 / 予定 '+e.line+'：':''}${esc(e.title||'')} ${esc(e.reason)}</p>`).join('')}${result.errors.length>8?'<p>ほかの行も対応形式に揃えてから取り込んでください。</p>':''}</details>`:''}<p>確認した内容だけを追加・更新します。現在の全データをバックアップしてから実行します。</p><div class="form-actions"><button class="secondary-button" data-action="integrations">キャンセル</button><button class="primary-button" data-action="apply-import" ${count?'':'disabled'}>${count}件を取り込む</button></div></div>`);
}
function moveEvent(id,date,minute) {
  const event=state.data.events.find(e=>e.id===id);if(!event)return;
  const duration=minutesOf(event.end)-minutesOf(event.start),start=Math.max(0,Math.min(1439-duration,Math.round(minute/5)*5));
  const next={...event,date,start:timeOf(start),end:timeOf(start+duration)};
  if(scheduleConflict(state.data.events,next,id)){toast('別の予定と重なるため、移動できません。');return;}
  Object.assign(event,next);state.selectedDay=date;save();render();toast('予定を移動しました。');
}
function dropAt(id,x,y) {
  const column=document.elementFromPoint(x,y)?.closest('.calendar-column');if(!column)return;
  moveEvent(id,column.dataset.date,y-column.getBoundingClientRect().top);
}
document.addEventListener('dragstart',e=>{const item=e.target.closest('.calendar-event');if(!item)return;state.dragId=item.dataset.id;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',item.dataset.id);});
document.addEventListener('dragover',e=>{if(state.dragId&&e.target.closest('.calendar-column')){e.preventDefault();e.dataTransfer.dropEffect='move';}});
document.addEventListener('drop',e=>{if(!state.dragId)return;e.preventDefault();const id=state.dragId;state.dragId=null;dropAt(id,e.clientX,e.clientY);});
document.addEventListener('dragend',()=>{state.dragId=null;});
let touchDrag;
document.addEventListener('pointerdown',e=>{const item=e.target.closest('.calendar-event');if(!item||e.pointerType==='mouse')return;touchDrag={id:item.dataset.id,x:e.clientX,y:e.clientY,active:false,item};touchDrag.timer=setTimeout(()=>{if(touchDrag){touchDrag.active=true;item.classList.add('dragging');}},320);});
document.addEventListener('pointermove',e=>{if(!touchDrag)return;if(!touchDrag.active&&Math.hypot(e.clientX-touchDrag.x,e.clientY-touchDrag.y)>8){clearTimeout(touchDrag.timer);touchDrag=null;return;}if(touchDrag.active){e.preventDefault();touchDrag.x=e.clientX;touchDrag.y=e.clientY;}},{passive:false});
const finishTouch=(e,cancel=false)=>{if(!touchDrag)return;const d=touchDrag;clearTimeout(d.timer);touchDrag=null;d.item.classList.remove('dragging');if(d.active){state.ignoreClickUntil=Date.now()+600;if(!cancel)dropAt(d.id,e.clientX,e.clientY);}};
document.addEventListener('pointerup',e=>finishTouch(e));document.addEventListener('pointercancel',e=>finishTouch(e,true));
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-action]');if(!b)return;
  if(b.dataset.action==='export-csv')download(exportCSV(state.data,b.dataset.type),`tsumikasane-${b.dataset.type}-${today()}.csv`,'text/csv;charset=utf-8');
  else if(b.dataset.action==='export-ics')download(exportICS(state.data.events),`tsumikasane-schedule-${today()}.ics`,'text/calendar;charset=utf-8');
  else if(b.dataset.action==='import-csv')importFileModal('csv');else if(b.dataset.action==='import-ics')importFileModal('ics');
  else if(b.dataset.action==='apply-plan'){
    const {date}=state.planDraft,result=planDay(state.data.tasks,state.data.events,date);
    state.data.events.push(...result.proposed.map(item=>({...item,id:uid()})));state.selectedDay=date;state.calendarAnchor=date;save();$('#modal').close();render();toast(result.proposed.length+'件の予定を仮配置しました。');
  }else if(b.dataset.action==='apply-import'){
    const {type,result}=transferDraft,next={...state.data,[type]:state.data[type].map(item=>result.updates?.find(updated=>updated.id===item.id)||item).concat(result.items)};
    if(!validateData(next)){toast('取り込めません。データの形式・件数を確認してください。');return;}
    if(loadWarning){toast('元の保存データを設定から保護して、JSONバックアップの復元で修復してください。');return;}
    download(JSON.stringify(state.data,null,2),`tsumikasane-before-import-${today()}.json`);state.data=normalizeData(next);for(const t of result.items)if(type==='tasks')recordTask(state.data,t,'imported',new Date(),'csv');save();$('#modal').close();render();toast('データを取り込みました。');
  }
});
document.addEventListener('change',async e=>{
  const target=e.target;
  if(target.id==='field-windowPreset'){
    const w=WINDOWS[target.value];if(w){$('#field-preferredStart').value=w.start;$('#field-preferredEnd').value=w.end;refreshWheels($('#modal-content'));}
  }else if(target.id==='field-preferredStart'||target.id==='field-preferredEnd'){
    const value=$('#field-windowPreset');if(value)value.value=Object.keys(WINDOWS).find(k=>WINDOWS[k].start===$('#field-preferredStart').value&&WINDOWS[k].end===$('#field-preferredEnd').value)||'custom';
  }else if(target.id==='field-planner-date'){if(target.value)updatePlanPreview(target.value);}
  else if(target.id==='field-taskId'){
    const task=state.data.tasks.find(t=>t.id===target.value);if(task){const start=taskWindow(task).start;$('#field-start').value=start;$('#field-end').value=timeOf(Math.min(minutesOf(start)+task.estimate,1439));$('#field-duration').value=minutesOf($('#field-end').value)-minutesOf(start);refreshWheels($('#modal-content'));}
  }else if(target.id==='field-start'||target.id==='field-duration'){
    const duration=$('#field-duration');if(duration){const end=minutesOf($('#field-start').value)+Number(duration.value);if(end>1439){$('#form-error').textContent='この長さでは日付をまたぎます。開始か長さを調整してください。';}else{$('#field-end').value=timeOf(end);$('#form-error').textContent='';refreshWheels($('#modal-content'));}}
  }else if(target.id==='field-end'){
    const duration=$('#field-duration');if(duration){const minutes=minutesOf(target.value)-minutesOf($('#field-start').value);if(minutes>0){duration.value=minutes;refreshWheels($('#modal-content'));}}
  }else if(target.id==='transfer-file'){
    const file=target.files[0],error=$('#transfer-error');if(!file)return;
    if(file.size>5*1024*1024){error.textContent='ファイルは5MB以内にしてください。';return;}
    const kind=target.dataset.kind,type=$('#csv-type')?.value;
    try{const text=await file.text();if(kind==='csv')csvMappingModal(parseCSV(text),type);else reviewImport('events',importICS(text,state.data.events));}catch(err){if(error.isConnected)error.textContent=err.message;}
  }
});

const ACTION_LABELS={created:'作成',updated:'編集',completed:'完了',reopened:'完了を取り消し',archived:'アーカイブ',restored:'復元',imported:'取り込み'};
function assetsPage(){
  const limit=state.historyLimit||50,history=state.data.history.slice().sort((a,b)=>(b.occurredAt||b.date||'').localeCompare(a.occurredAt||a.date||'')),archive=state.data.archive;
  const dateText=e=>e.occurredAt?new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',dateStyle:'medium',timeStyle:'short'}).format(new Date(e.occurredAt)):e.date?fmt(e.date)+'（日付のみ）':'日時不明・元データの状態を保持';
  return heading('YOUR PROGRESS BELONGS TO YOU','積み重ねた、自分の資産。','完了したことも、やり直したことも。履歴を残して、いつでも持ち出せる。',`<div class="asset-toolbar"><button class="primary-button" data-action="export">${icon('download')}全データJSON</button><button class="secondary-button" data-action="export-history">達成履歴CSV</button></div>`)+`<div class="storage-banner"><span data-cloud-status>${esc(state.demo?'サンプル：この端末に保存':cloudStatus)}</span><button class="text-button" data-action="cloud-review">保存状態を確認</button></div><div class="stats"><div class="stat-card"><div><div class="stat-label">記録してきた履歴</div><div class="stat-value">${history.length}<small>件</small></div></div></div><div class="stat-card"><div><div class="stat-label">アーカイブしたタスク</div><div class="stat-value">${archive.tasks.length}<small>件</small></div></div></div><div class="stat-card"><div><div class="stat-label">保管した元データ</div><div class="stat-value">${state.data.sourceTables.length}<small>表</small></div></div></div></div><div class="asset-grid"><section class="panel asset-card"><h2>タスクの達成・変更履歴</h2><p>完了を取り消しても、以前の完了履歴は残ります。日付だけ分かる過去の記録は、その精度で保持します。</p>${history.length?history.slice(0,limit).map(e=>`<div class="asset-row"><span class="asset-badge">${ACTION_LABELS[e.action]}</span><div><strong>${esc(e.snapshot.title)}</strong><small>${esc(dateText(e))} · ${e.origin==='app'?'アプリ':e.origin==='notion'?'Notion':'取り込みデータ'}</small></div></div>`).join(''):empty('最初のタスクを作成すると、ここに履歴が残ります。')}${history.length>limit?'<button class="secondary-button asset-more" data-action="history-more">さらに50件を見る</button>':''}</section><div><section class="panel asset-card"><h2>データを持ち出す</h2><div class="settings-buttons"><button class="secondary-button" data-action="export-all-tasks">全タスクCSV</button><button class="secondary-button" data-action="export-all-logs">全作業ログCSV</button><button class="secondary-button" data-action="export-history">達成履歴CSV</button></div><p class="asset-help">CSVにはアーカイブ分も含みます。タスクID・完了日・完了日時を出力し、他のアプリで照合できます。全データJSONは、元データ・履歴・振り返りを含む復元用です。</p><button class="secondary-button" data-action="import-notion">Notion ZIPを取り込む</button></section><section class="panel asset-card" style="margin-top:24px"><h2>アーカイブから戻す</h2>${['tasks','logs','events'].flatMap(type=>archive[type].map(item=>({type,item}))).slice(-30).reverse().map(({type,item})=>`<div class="asset-row"><div><strong>${esc(item.title)}</strong><small>${{tasks:'タスク',logs:'作業ログ',events:'予定'}[type]} · ${esc(item.due||item.date||'期限なし')}</small></div><button class="secondary-button" data-action="restore-item" data-type="${type}" data-id="${esc(item.id)}">復元</button></div>`).join('')||'<p>アーカイブはまだありません。</p>'}</section></div></div><section class="panel asset-card" style="margin-top:24px"><h2>移行元のデータも、そのまま保管</h2><p>アプリの項目に割り当てられない列や、目標・健康・ページ本文もCSVで書き出せます。元の列名と値を保持します。</p>${state.data.sourceTables.map(t=>`<div class="source-table-row"><span>${esc(t.name)}<br><small>${t.rows.length}行 · ${t.headers.length}列</small></span><button class="secondary-button" data-action="export-source" data-id="${esc(t.id)}">CSV</button></div>`).join('')||'<p>Notion ZIPを取り込むと、ここに元データが残ります。</p>'}</section>`;
}
function updateCloudStatus(text){cloudStatus=text;if(state.demo)return;$('#save-status').textContent=text;for(const el of document.querySelectorAll('[data-cloud-status]'))el.textContent=text;}
function updateDeviceStatus(status){
  cloudStatus=status;const text=state.demo?'サンプル · '+status:status;
  if($('#device-save-status'))$('#device-save-status').textContent=text;
  $('#save-status').textContent=text;for(const el of document.querySelectorAll('[data-cloud-status]'))el.textContent=text;
}
function deviceReview(){
  modal('この端末だけに保存',`<div class="settings-content"><p>${esc(deviceStorage?.status||deviceError)}</p><p>タスク・予定・記録・達成履歴は、このブラウザの端末内に保存します。クラウドへの送信や端末間の自動同期は行いません。</p><p>ブラウザのデータを消すと記録も消えます。端末内保存は暗号化やアプリロックを追加するものではありません。端末のロックとJSONバックアップを利用してください。</p><div class="settings-buttons"><button class="primary-button" data-action="export">全データJSONを書き出す</button><button class="secondary-button" data-action="device-retry">保存を再試行</button><button class="secondary-button" data-action="device-persist">保存領域の保持をリクエスト</button></div><p id="device-persist-status" class="field-hint">保存領域の保持はブラウザが判断します。データ削除の操作を防ぐものではありません。</p></div>`);
}
const cloud=DEVICE_ONLY?{ready:!!deviceStorage,queued:null,conflict:null,refresh:async()=>{}}:new CloudStore({read,write,onStatus:updateCloudStatus,onData:data=>{write('tsumikasane-data-v1-personal',JSON.stringify(data));if(!state.demo){state.data=data;render();}},onConflict:()=>{if(!state.demo)toast('別の端末の保存内容と違いがあります。履歴・データから確認してください。');}});
async function bootCloud(){if(DEVICE_ONLY){document.body.dataset.cloudReady='true';updateDeviceStatus(deviceStorage?.status||'端末内の保存領域を利用できません');return;}document.body.dataset.cloudReady='false';if(loadWarning){cloud.ready=true;updateCloudStatus('元の保存データの復元が必要');return;}await cloud.init(read('tsumikasane-data-v1-personal')?state.data:null);document.body.dataset.cloudReady='true';}
function cloudReview(){
  if(DEVICE_ONLY){deviceReview();return;}
  if(state.demo){toast('自分のデータで、クラウド保存を利用できます。');return;}
  if(cloud.conflict){modal('保存内容の違いを確認',`<div class="settings-content"><p>別の端末の内容と、この端末の未保存データに違いがあります。置き換える前に、選ばなかった側をJSONでダウンロードします。</p><div class="settings-buttons"><button class="secondary-button" data-action="cloud-use-remote">クラウドの内容を使う</button><button class="primary-button" data-action="cloud-use-local">この端末の内容を保存</button></div></div>`);}
  else modal('データの保存状態',`<div class="settings-content"><p>${esc(cloudStatus)}</p>${cloud.signInPath?`<a class="primary-button" href="${esc(cloud.signInPath)}" target="_top">ログインして保存を再開</a>`:''}<p>自分のデータはログイン中のアカウント専用のクラウドへ保存します。通信できない間は、この端末の控えに残します。保存済みの確認と、JSONの書き出しを併用できます。</p><div class="settings-buttons"><button class="secondary-button" data-action="export">全データを書き出す</button><button class="primary-button" data-action="cloud-retry">接続を再確認</button></div></div>`);
}
async function notionImportModal(){
  if(state.demo){state.demo=false;write('tsumikasane-mode','personal');state.data=load();loadTimer();render();await bootCloud();}
  modal('NotionのZIPを取り込む',`<div class="settings-content"><p>Notionで書き出した「Markdown & CSV」のZIPを、そのまま選択してください。タスク・作業ログ・予定・振り返りを取り込み、その他の項目は元データとして保管します。</p><div class="import-options"><label for="notion-year">年が省略された日付の年</label><input id="notion-year" type="number" min="1900" max="2200" value="${today().slice(0,4)}"><label for="notion-unit">「見積残時間」の単位</label><select id="notion-unit" class="theme-select"><option value="">未確認（30分を仮設定）</option><option value="hours">時間（1＝60分）</option><option value="minutes">分（1＝1分）</option></select><label><input id="notion-archive" type="checkbox" checked> 過去の日次タスクはアーカイブへ保管</label></div><input type="file" id="notion-file" accept=".zip,application/zip" aria-label="Notion ZIPを選択"><p class="form-error" id="notion-error" role="alert"></p><p class="field-hint">25MB以内。元データの指示文は実行せず、取り込み・保管する文字列として扱います。</p></div>`);
}
function notionPreview(result){
  state.notionDraft=result;const d=result.data;
  modal('Notionからの取り込み内容',`<div class="settings-content"><div class="import-counts"><strong>タスク ${d.tasks.length}件</strong><strong>過去のタスク ${d.archive.tasks.length}件</strong><span>作業ログ ${d.logs.length}件</span><span>予定 ${d.events.length}件</span><span>振り返り ${Object.keys(d.reflections).length}日</span><span>元データ ${d.sourceTables.length}表</span><span>重複 ${result.duplicates}件</span></div>${result.warnings.length?`<div class="notion-warning">${result.warnings.map(w=>esc(w)).join('<br>')}</div>`:''}${result.errors.length?`<details class="import-details" open><summary>項目に割り当てられなかった内容 ${result.errors.length}件</summary>${result.errors.slice(0,8).map(e=>`<p>${esc(e.table)} ${e.line}行：${esc(e.reason)}</p>`).join('')}<p>元の値は「元データ」として保持します。</p></details>`:''}<p>現在のデータを書き出してから追加します。Notionのファイルや既存データは削除しません。</p><div class="form-actions"><button class="secondary-button" data-action="close-modal">キャンセル</button><button class="primary-button" data-action="apply-notion">確認して取り込む</button></div></div>`);
}
document.addEventListener('change',async e=>{
  if(e.target.id!=='notion-file')return;const file=e.target.files[0];if(!file)return;
  const error=$('#notion-error'),year=Number($('#notion-year').value),estimateUnit=$('#notion-unit').value,archivePast=$('#notion-archive').checked;
  if(!Number.isInteger(year)||year<1900||year>2200){error.textContent='年を1900〜2200で指定してください。';return;}
  error.textContent='ZIPを確認しています…';
  try{const archive=readNotionZip(new Uint8Array(await file.arrayBuffer()));const result=await importNotionZip(archive,state.data,{year,estimateUnit,archivePast});notionPreview(result);}catch(err){if(error.isConnected)error.textContent=err.message;}
});
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
  if(a==='history-more'){state.historyLimit=(state.historyLimit||50)+50;render();}
  else if(a==='device-retry'){deviceStorage?.flush().then(ok=>toast(ok?'この端末に保存しました。':'保存できません。全データJSONを書き出してください。'));}
  else if(a==='device-persist'){(async()=>{const granted=await navigator.storage?.persist?.();const message=$('#device-persist-status');if(message)message.textContent=granted?'保存領域の保持が許可されています。JSONバックアップも保管してください。':'保持の許可は得られませんでした。JSONバックアップを保管してください。';})().catch(()=>toast('このブラウザでは保持のリクエストを利用できません。'));}
  else if(a==='export-history')download(exportHistory(state.data),'tsumikasane-task-history-'+today()+'.csv','text/csv;charset=utf-8');
  else if(a==='export-all-tasks')download(exportCSV({...state.data,tasks:[...state.data.tasks,...state.data.archive.tasks]},'tasks'),'tsumikasane-all-tasks-'+today()+'.csv','text/csv;charset=utf-8');
  else if(a==='export-all-logs')download(exportCSV({...state.data,logs:[...state.data.logs,...state.data.archive.logs]},'logs'),'tsumikasane-all-logs-'+today()+'.csv','text/csv;charset=utf-8');
  else if(a==='export-source'){const table=state.data.sourceTables.find(t=>t.id===id);if(table)download(exportSourceTable(table),table.name.replace(/[\\/:*?"<>|]/g,'_')+'.csv','text/csv;charset=utf-8');}
  else if(a==='restore-item'){if(!['tasks','events','logs'].includes(b.dataset.type))return;if(restoreItem(state.data,b.dataset.type,id)){save();render();toast('復元しました。');}}
  else if(a==='cloud-review')cloudReview();
  else if(a==='cloud-retry'){$('#modal').close();if(cloud.queued)cloud.flush();else bootCloud();}
  else if(a==='cloud-use-remote'||a==='cloud-use-local'){if(!cloud.conflict)return;download(JSON.stringify(a==='cloud-use-remote'?cloud.conflict.local:cloud.conflict.remote,null,2),'tsumikasane-conflict-backup-'+today()+'.json');cloud.resolve(a==='cloud-use-remote');$('#modal').close();}
  else if(a==='import-notion')notionImportModal();
  else if(a==='apply-notion'){
    const d=state.notionDraft.data,next={...state.data,tasks:state.data.tasks.concat(d.tasks),events:state.data.events.concat(d.events),logs:state.data.logs.concat(d.logs),history:state.data.history.concat(d.history),reflections:{...state.data.reflections,...d.reflections},sourceTables:state.data.sourceTables.concat(d.sourceTables),archive:{tasks:state.data.archive.tasks.concat(d.archive.tasks),events:state.data.archive.events,logs:state.data.archive.logs}};
    if(!validateData(next)||new TextEncoder().encode(JSON.stringify(next)).length>9*1024*1024){toast('取り込み後のデータが大きすぎるか、形式が一致しません。');return;}
    if(loadWarning){toast('先に、読み込めなかった保存データを復元してください。');return;}
    download(JSON.stringify(state.data,null,2),'tsumikasane-before-notion-'+today()+'.json');state.data=next;save();$('#modal').close();state.page='assets';location.hash='assets';render();toast('Notionのデータを取り込みました。');
  }
});
window.addEventListener('online',()=>{if(!DEVICE_ONLY&&!state.demo){if(cloud.queued)cloud.flush();else bootCloud();}});
window.addEventListener('focus',()=>{if(!DEVICE_ONLY&&!state.demo&&!$('#modal').open&&!document.activeElement?.matches('textarea,input'))cloud.refresh();});

function navigate(){const p=location.hash.slice(1);state.page=['today','tasks','schedule','records','assets'].includes(p)?p:'today';state.filter='all';render();}
window.addEventListener('hashchange',navigate);
let lastToday=today();
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&lastToday!==today()){if(state.selectedDay===lastToday)state.selectedDay=today();if(state.recordDay===lastToday)state.recordDay=today();lastToday=today();render();}});
if(DEVICE_ONLY){
  const banner=document.createElement('div');banner.className='device-status';banner.innerHTML='<span>端末内テスト版 · <span id="device-save-status"></span></span><button class="text-button" data-action="cloud-review">保存とバックアップ</button>';$('.topbar').after(banner);
  deviceStorage?.subscribe(updateDeviceStatus);
  window.addEventListener('beforeunload',event=>{if(deviceStorage?.pending){event.preventDefault();event.returnValue='';}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden)deviceStorage?.flush();});
}
navigate();
if(!state.demo)bootCloud();
